# Cross-Archive Identifier Matcher - runnable demo (JAH-ATK193-000001)
import re
RANK = 1
SIG = False
ARCH_A, ARCH_B = [[('a1', '978-0-13-110362-7'), ('a2', '9780262033848')], [('b7', '9780131103627'), ('b9', '978-0-262-03384-8'), ('b2', '0000000000')]]  # lists of (local_id, isbn_raw)
def norm_isbn(s):
    return re.sub(r"[^0-9X]", "", s.upper())
na = {norm_isbn(i): lid for lid, i in ARCH_A}
nb = {norm_isbn(i): lid for lid, i in ARCH_B}
links = []
for isbn, la in na.items():
    if isbn in nb: links.append((la, nb[isbn], isbn))
print("archive A records:", len(ARCH_A), "| archive B records:", len(ARCH_B))
for la, lb, isbn in links:
    print("  LINK %s <-> %s via ISBN %s" % (la, lb, isbn))
unlinked_a = [la for la in [x[0] for x in ARCH_A] if la not in [l[0] for l in links]]
if RANK >= 2: print("unlinked in A:", unlinked_a if unlinked_a else "none")
if RANK >= 3: print("link coverage: %d/%d" % (len(links), len(ARCH_A)))
if SIG:
    print("Signature lineage stamp: JAH-SIG-IDM-" + "JAH-ATK193-000001")
print("record:", "JAH-ATK193-000001", "OK")

